  ('dc80d8ab-4c64-45f8-b0a1-840da565760c', $$Scheikunde$$, $$VWO$$, $$Kerosine uit zonlicht$$, $$VWO Scheikunde 2017-II$$),
  ('65bad1bb-d26a-4901-a503-e24bb8e089d6', $$Scheikunde$$, $$VWO$$, $$KNOxOUT™-verf$$, $$VWO Scheikunde 2017-II$$),
