  ('f2c4ed1f-d0ce-4ce0-893a-f4d6e87ba169', $$Scheikunde$$, $$VWO$$, $$Zwetende gebouwen koelen af$$, $$VWO Scheikunde 2017-II$$),
  ('0f6ea0db-b8b6-49dd-9dfc-7edc8c28ccca', $$Scheikunde$$, $$VWO$$, $$De bacteriële celwand$$, $$VWO Scheikunde 2017-II$$);

insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('32b7b5ec-7b39-4035-b065-1767623181f5', 'dc80d8ab-4c64-45f8-b0a1-840da565760c', $$reactie 1 — vorming van CO en H₂ uit CO₂ en water (1000 K)$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-ii-kerosine-context1.png$$,
   $$Europese chemici produceren vliegtuigbrandstof (kerosine) uit koolstofdioxide en water met een solar-reactor, waarin gebundeld zonlicht een zeer hoge temperatuur veroorzaakt. Bij 1000 K verloopt reactie 1 tussen koolstofdioxide en water: 4 H₂O + 2 CO₂ → 2 CO + 4 H₂ + 3 O₂ (reactie 1).$$, 'inline'),
  ('113ee20d-bbc2-45d0-b2f5-aeac745eab89', 'dc80d8ab-4c64-45f8-b0a1-840da565760c', $$cerium(III)oxide vangt zuurstof weg (reactie 2)$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-ii-kerosine-context2.png$$,
   $$De gevormde zuurstof moet worden verwijderd voordat het gasmengsel verder gebruikt kan worden. Daarvoor is in de reactor een fijn gaas aangebracht, bedekt met cerium(III)oxide. Als cerium(III)oxide reageert met zuurstof ontstaat cerium(IV)oxide (reactie 2). Uiteindelijk wordt door reacties 1 en 2 een mengsel van CO en H₂ verkregen.$$, 'inline'),
  ('7df4e1b7-2f17-4bdf-85ad-c591edeea6a2', 'dc80d8ab-4c64-45f8-b0a1-840da565760c', $$reactie 3 — regeneratie van cerium(III)oxide, continuproces$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-ii-kerosine-context3.png$$,
   $$Het gevormde cerium(IV)oxide kan door sterke verhitting weer worden omgezet tot cerium(III)oxide (reactie 3). De onderzoekers willen reacties 1 en 2 uitvoeren met een continue instroom en uitstroom van de gassen. Om de productie van CO en H₂ als continuproces te laten verlopen, moeten reacties 1 en 3 tegelijk plaatsvinden.$$, 'inline'),
  ('8a6a3069-2f6e-4c8b-aa4c-b421b158aba7', 'dc80d8ab-4c64-45f8-b0a1-840da565760c', $$Fischer-Tropsch-proces — vorming van kerosine (C₁₄H₂₈)$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-ii-kerosine-context4.png$$,
   $$Het gasmengsel waar de zuurstof uit is verwijderd (syngas) wordt met het Fischer-Tropsch-proces omgezet tot kerosine. De gevormde kerosine had een gemiddelde molecuulformule van C₁₄H₂₈. Als bijproduct ontstond alleen water.$$, 'inline'),
  ('ac8885c5-802a-4254-be1a-8a20fa5c0336', '65bad1bb-d26a-4901-a503-e24bb8e089d6', $$NOₓ-uitstoot en gemeten NO₂-percentage in Makati$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-ii-knoxout-context1.png$$,
   $$Stikstofoxiden (NOₓ) worden voornamelijk uitgestoten door motorvoertuigen en veroorzaken luchtvervuiling en zure regen. Vooral het roodbruine NO₂ is giftig en veroorzaakt smog. In Makati (Filipijnen) ging een project van start om de NOₓ-uitstoot te verminderen. Het gemeten gemiddelde volumepercentage NO₂ op de plek van het project (metrostation Guadalupe) was in 2009 meer dan 9,6·10⁻⁶ %.$$, 'inline'),
  ('f32226aa-4f02-45ba-ae1b-c041f828414d', '65bad1bb-d26a-4901-a503-e24bb8e089d6', $$TiO₂-katalysator zet water en zuurstof om (reactie 1)$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-ii-knoxout-context2.png$$,
   $$In Makati werd metrostation Guadalupe geverfd met KNOxOUT™-verf van de Filipijnse firma Boysen, waardoor de NOₓ-concentratie drastisch daalde. Dit komt door de katalysator TiO₂ in de verf: TiO₂ zet water- en zuurstofmoleculen onder invloed van uv-straling om volgens reactie 1: H₂O + O₂ → H⁺ + HO• + O₂•⁻ (reactie 1).$$, 'inline'),
  ('4e7cca14-c08b-43f2-8b3b-c09ac32a901f', '65bad1bb-d26a-4901-a503-e24bb8e089d6', $$vorming van salpeterzuur uit NOₓ; neutralisatie door CaCO₃$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-ii-knoxout-context3.png$$,
   $$De gevormde deeltjes reageren met NOₓ tot salpeterzuur; uit elk deeltje NOₓ ontstaat één deeltje salpeterzuur. Het gevormde salpeterzuur wordt vervolgens door het in de verf aanwezige calciumcarbonaat (CaCO₃) volledig geneutraliseerd, waarbij CO₂ en opgelost calciumnitraat ontstaan. Deze stoffen spoelen tijdens een regenbui weg.$$, 'inline'),
  ('e785b5e4-faff-42d7-9f27-12369ec91312', '65bad1bb-d26a-4901-a503-e24bb8e089d6', $$geverfd oppervlak in Makati; NOₓ-omzetting per m² per dag$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-ii-knoxout-context4.png$$,
   $$In het experiment in Makati werd in totaal 4100 m² muur geverfd. Gemiddeld zette de verf per m² muur 0,26 gram aan NOₓ per dag om tot salpeterzuur. Er is gepland om de muur elke vijf jaar opnieuw te verven.$$, 'inline'),
  ('82619aac-c48e-4b98-ae1b-e6c9530cce09', '4224a8a5-4ba9-4803-96ff-45e5770c3517', $$natriumsilicide NaSi — Na⁺- en Si₄⁴⁻-ionen, tetraëdrische vorm$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-ii-batterijen-context1.png$$,
   $$In 2012 werd een draagbare batterijoplader gepresenteerd met een eenmalig te gebruiken capsule natriumsilicide. Het natriumsilicide wordt bereid door siliciumpoeder en vloeibaar natrium met elkaar te laten reageren bij 400 °C. De verhoudingsformule van natriumsilicide is NaSi; het is opgebouwd uit Na⁺- en Si₄⁴⁻-ionen. Een Si₄⁴⁻-ion heeft de vorm van een tetraëder, met op elk hoekpunt een Si-deeltje.$$, 'inline'),
  ('630ebc2b-b199-4f2f-9c83-eccd9e568d01', '4224a8a5-4ba9-4803-96ff-45e5770c3517', $$reactie 1 — NaSi met water naar Na₂Si₂O₅ en waterstof; capsulegegevens$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-ii-batterijen-context2.png$$,
   $$In de oplader wordt het natriumsilicide in contact gebracht met water, waarbij waterstof ontstaat (reactie 1): 2 NaSi (s) + 5 H₂O (l) → Na₂Si₂O₅ (s) + 5 H₂ (g). Een capsule bevat 4,5 g natriumsilicide-poeder en levert 4,0 L waterstofgas (T = 298 K, p = p₀).$$, 'inline'),
  ('f416852a-1986-4429-8230-33ed6de897a5', '4224a8a5-4ba9-4803-96ff-45e5770c3517', $$waterstofbrandstofcel; titel ‘Mobieltje opladen met water’$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-ii-batterijen-context3.png$$,
   $$De gevormde waterstof stroomt naar een waterstofbrandstofcel in de oplader, waar de waterstof wordt omgezet tot water. Bijzonder is dat de oplader vóór gebruik gevuld moet worden met water; een persbericht kreeg daarom als titel ‘Mobieltje opladen met water’, wat lijkt te suggereren dat de oplader zijn energie uit water haalt.$$, 'inline'),
  ('d580e96c-76f1-4564-aa21-a87edcb9e310', '4224a8a5-4ba9-4803-96ff-45e5770c3517', $$duurzaamheidspunten van de fabrikant$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-ii-batterijen-context4.png$$,
   $$De oplader wordt aangeprezen als duurzaam. De fabrikant noemt: natriumsilicide wordt bereid uit ruimschoots aanwezige grondstoffen (natriumchloride en siliciumdioxide/zand); de vorming van natriumsilicide uit natrium en silicium kost geen energie en levert geen bijproduct op; tijdens stroomlevering komt alleen waterdamp in de atmosfeer; de capsule kan na gebruik bij het gewone afval omdat ze geen schadelijke stoffen bevat.$$, 'inline'),
  ('dec1d19d-dd79-4110-9895-98ed33f43853', '4224a8a5-4ba9-4803-96ff-45e5770c3517', $$extra capsule met natriumboorhydride (NaBH₄)$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-ii-batterijen-context5.png$$,
   $$Om de waterstofproductie per gram poeder te verhogen is een andere capsule ontwikkeld met naast natriumsilicide ook natriumboorhydride (NaBH₄). De reactie tussen natriumsilicide-poeder en water verloopt snel en exotherm; natriumboorhydride-poeder reageert zuiver maar heel langzaam met water. In het mengsel van beide poeders worden opmerkelijk genoeg beide stoffen snel omgezet.$$, 'inline'),
  ('61718862-4dfd-4bf8-9d19-2bd864350bb8', '4224a8a5-4ba9-4803-96ff-45e5770c3517', $$rendement van het mengsel: max. 15,7 g waterstof per 100 g; reactie 2$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-ii-batterijen-context6.png$$,
   $$De fabrikant vermeldt niet in welke verhouding de twee stoffen gemengd zijn, maar wel dat 100 g van het mengsel na reactie met water maximaal 15,7 g waterstof kan leveren. Uit de reactie van natriumboorhydride met water ontstaan waterstof, natriumhydroxide en B(OH)₃ (reactie 2).$$, 'inline'),
  ('f83adb88-8bef-4c33-a1b0-9a12ee1398b8', 'f2c4ed1f-d0ce-4ce0-893a-f4d6e87ba169', $$hydrogel van pHEMA; structuurformule van HEMA$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-ii-zwetend-context1.png$$,
   $$Het koelen van kantoorgebouwen kost veel energie. Een manier om dit te verminderen is het dak te bedekken met sponsachtig materiaal dat regenwater opneemt en later verdampt, waardoor het gebouw minder opwarmt. Onderzocht is of een hydrogel — een homogeen mengsel van een polymeer met water, waarbij interacties tussen de polymeerketens ontmenging voorkomen — hiervoor geschikt is. Eerst is de hydrogel van het polymeer pHEMA onderzocht: pHEMA is het additiepolymeer van HEMA. Structuurformule van HEMA: HO-CH₂-CH₂-O-C(=O)-C(CH₃)=CH₂.$$, 'inline'),
  ('006b2179-e9ff-4c71-af0a-b941d2e8363d', 'f2c4ed1f-d0ce-4ce0-893a-f4d6e87ba169', $$bereiding pHEMA — ammoniumpersulfaat en initiatiereactie (S₂O₈²⁻ → 2 SO₄•⁻)$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-ii-zwetend-context2.png$$,
   $$pHEMA wordt bereid door aan een mengsel van HEMA met water een kleine hoeveelheid ammoniumpersulfaat, (NH₄)₂S₂O₈, toe te voegen. De initiatiereactie van de polymerisatie is: S₂O₈²⁻ → 2 SO₄•⁻ (initiatie). Het deeltje SO₄•⁻ is het radicaal dat de polymerisatie op gang brengt.$$, 'inline'),
  ('9f11c75d-412e-4d43-8545-c8e333baf0ef', 'f2c4ed1f-d0ce-4ce0-893a-f4d6e87ba169', $$het radicaal SO₄•⁻ reageert met HEMA tot pHEMA$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-ii-zwetend-context3.png$$,
   $$Het radicaal SO₄•⁻ reageert met HEMA, waardoor uiteindelijk pHEMA ontstaat.$$, 'inline'),
  ('bbc0e3ff-058e-4628-8a96-eff8ff1603cd', 'f2c4ed1f-d0ce-4ce0-893a-f4d6e87ba169', $$massapercentage water in verzadigde pHEMA-hydrogel (72%)$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-ii-zwetend-context4.png$$,
   $$pHEMA kan veel water opnemen. Als pHEMA geheel met water wordt verzadigd, bedraagt het massapercentage water in de ontstane hydrogel 72%.$$, 'inline'),
  ('ba35e552-955c-4dfe-8017-fa60eef63cb3', 'f2c4ed1f-d0ce-4ce0-893a-f4d6e87ba169', $$figuur 1 — microstructuur van pNIPAM (netwerkpolymeer van twee monomeren)$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-ii-zwetend-context5.png$$,
   $$Omdat pHEMA in de praktijk tegenviel, is het verwante polymeer pNIPAM onderzocht. In figuur 1 is een gedeelte van de microstructuur van pNIPAM weergegeven: pNIPAM is een netwerkpolymeer dat uit twee monomeren wordt gemaakt, waarbij bij de polymerisatie uitsluitend additiereacties optreden. Figuur 1 toont twee parallelle polymeerketens (elk opgebouwd uit CH-CH₂-eenheden met telkens een -C(=O)-NH-CH(CH₃)-CH₃-zijgroep per CH). Eén CH-eenheid in elke keten draagt in plaats van die zijgroep een -C(=O)-NH-CH₂-NH-C(=O)- brug die de twee ketens met elkaar verbindt (de crosslink).$$, 'inline'),
  ('b3a8abdd-05e0-46d1-acac-d247216e21dd', 'f2c4ed1f-d0ce-4ce0-893a-f4d6e87ba169', $$pNIPAM neemt water op onder 33 °C; verwijzing naar de uitwerkbijlage bij vraag 22$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-ii-zwetend-context6.png$$,
   $$Als pNIPAM-korrels bij een temperatuur onder 33 °C met water worden samengevoegd, zwelt het materiaal op door opname van water; ketendelen van pNIPAM worden dan volledig omgeven door watermoleculen. Op de uitwerkbijlage is figuur 1 nogmaals weergegeven.$$, 'inline'),
  ('28178354-2168-49d4-b6c5-9722aedce751', 'f2c4ed1f-d0ce-4ce0-893a-f4d6e87ba169', $$pHEMA vormt bij opdrogen een harde korst door kristallijne gebieden$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-ii-zwetend-context7.png$$,
   $$Een dak bedekt met pNIPAM-korrels neemt tijdens regen water op; als de zon schijnt neemt de natte hydrogel energie op en verdampt het water, waardoor het gebouw minder opwarmt. Omdat dit herhaalbaar is, kan het materiaal lang gebruikt worden. Het eerder onderzochte pHEMA is hiervoor niet geschikt, omdat bij het verdampen van water een harde korst van pHEMA ontstaat die wateropname belemmert. De onderzoekers veronderstellen dat dit komt doordat de polymeerketens van pHEMA zich tijdens het opdrogen regelmatig rangschikken, waardoor kristallijne gebieden ontstaan met zulke sterke interacties tussen de ketens dat watermoleculen er niet meer tussen kunnen dringen.$$, 'inline'),
  ('d04d971f-3bd0-4e98-b491-491f06065dc1', 'f2c4ed1f-d0ce-4ce0-893a-f4d6e87ba169', $$temperatuurmeting pNIPAM-laag op miniatuurhuis (24 °C → 33 °C, daarna verdamping)$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-ii-zwetend-context8.png$$,
   $$Om de koelende werking van pNIPAM te onderzoeken zijn temperatuurmetingen gedaan aan een miniatuurhuis met een dak bedekt met een laag pNIPAM-korrels, aan het begin verzadigd met water. Onder een sterke lamp steeg de temperatuur van de natte hydrogel van 24 °C tot 33 °C door opname van energie. Bij 33 °C bleef de temperatuur constant totdat al het water was verdampt; de op dat moment opgenomen energie hoeft niet meer door koeling te worden afgevoerd.$$, 'inline'),
  ('a1a68ef0-eb06-4cab-9beb-99ca3ee4509d', 'f2c4ed1f-d0ce-4ce0-893a-f4d6e87ba169', $$uitwerkbijlage vraag 22 — figuur 1 (pNIPAM) nogmaals weergegeven$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-ii-zwetend-context9.png$$,
   $$uitwerkbijlage bij vraag 22: figuur 1 (de microstructuur van pNIPAM, twee parallelle ketens met een crosslink) is nogmaals afgedrukt, met ruimte om aan te geven hoe twee watermoleculen aan pNIPAM gebonden zijn.$$, 'uitwerkbijlage'),
  ('df4244fa-3ed6-4fa3-b75c-6cb7acba19af', '0f6ea0db-b8b6-49dd-9dfc-7edc8c28ccca', $$mureïne — sacharide-ketens en peptideketens in de bacteriële celwand$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-ii-celwand-context1.png$$,
   $$Bacteriën hebben naast een celmembraan ook een celwand. Het belangrijkste bestanddeel van deze celwand is mureïne, dat bestaat uit lange sacharide-ketens die door korte peptideketens met elkaar verbonden zijn. In de sacharide-keten komen afwisselend de eenheden NAG en NAM voor. In figuur 1 is een deel van de keten van mureïne weergegeven.$$, 'inline'),
  ('cddce7e8-c111-455f-9e22-a339456dad2b', '0f6ea0db-b8b6-49dd-9dfc-7edc8c28ccca', $$figuur 1 — schema van de sacharide-keten (NAG/NAM met substituenten R1 en R2)$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-ii-celwand-context2.png$$,
   $$figuur 1: het herhalende tweeledige sacharide-motief van mureïne (ringstructuren, n keer herhaald). Beide ringeenheden dragen een CH₂OH-groep en substituent R1 = -NH-C(=O)-CH₃ (een N-acetylgroep). De linker eenheid heeft daarnaast een vrije OH-groep; de rechter eenheid heeft in plaats daarvan substituent R2 = -O-CH(CH₃)-C(=O)- gevolgd door de peptideketen (aangeduid met genummerde cirkels 1, 2, 3 en een stippellijn voor de rest van de keten).$$, 'inline'),
  ('8ab7421f-99a8-4e03-92ef-3c05e240598f', '0f6ea0db-b8b6-49dd-9dfc-7edc8c28ccca', $$NAG en NAM zijn beide afgeleid van eenzelfde monosacharide (Binas-tabel 67F)$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-ii-celwand-context3.png$$,
   $$NAG en NAM zijn beide afgeleid van één van de monosachariden die in Binas-tabel 67F zijn weergegeven.$$, 'inline'),
  ('aa653b29-ead9-4823-ae3e-363924ed85ed', '0f6ea0db-b8b6-49dd-9dfc-7edc8c28ccca', $$peptideketen aan R2 gebonden — aantal en samenstelling afhankelijk van bacteriesoort$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-ii-celwand-context4.png$$,
   $$Aan iedere NAM-eenheid is via R2 een korte peptideketen gebonden. Zowel het aantal aminozuren in de peptideketen als de samenstelling van de aminozuren is afhankelijk van de bacteriesoort. In figuur 2 is de peptideketen weergegeven die voorkomt in mureïne van de bacteriesoort E. coli. Aminozuur 2 in deze peptideketen is op een afwijkende manier in de keten opgenomen.$$, 'inline'),
  ('70d1be0d-7884-49d9-a702-7648b3bd6b2f', '0f6ea0db-b8b6-49dd-9dfc-7edc8c28ccca', $$figuur 2 — peptideketen in mureïne van E. coli (aminozuur 1 t/m 4)$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-ii-celwand-context5.png$$,
   $$figuur 2: de peptideketen die via R2 aan NAM in mureïne van E. coli vastzit, met vier genummerde aminozuren (1 t/m 4) die via amidebindingen (-C(=O)-NH-) een keten vormen. Aminozuur 1 heeft geen zijgroep aan de alfa-koolstof. Aminozuur 2 heeft een zijketen (-CH₂-CH₂-C(=O)-) die verderop naar de volgende amidebinding in de keten leidt, terwijl de gebruikelijke alfa-carbonzuurgroep van aminozuur 2 juist als vrije zijgroep (HO-C(=O)-) apart staat. Aminozuur 3 draagt aan het ene uiteinde een vrije aminogroep (H₂N-) en aan het andere een vrije carbonzuurgroep (-C(=O)-OH), en is via een keten van CH₂-groepen en een amidebinding gekoppeld aan aminozuur 4. Aminozuur 4 heeft een CH₃-zijgroep en een vrije eind-carbonzuurgroep (-C(=O)-OH).$$, 'inline'),
  ('70ad5085-5906-456e-99da-24ff4659f2e1', '0f6ea0db-b8b6-49dd-9dfc-7edc8c28ccca', $$aminozuur 3 in de peptideketen is diaminopimelinezuur (DAP)$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-ii-celwand-context6.png$$,
   $$Aminozuur 3 in de peptideketen bij E. coli is het zogeheten diaminopimelinezuur (DAP).$$, 'inline'),
  ('f8b130db-d6d5-41ff-90f4-90654350d775', '0f6ea0db-b8b6-49dd-9dfc-7edc8c28ccca', $$DAP is niet in Binas opgenomen$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-ii-celwand-context7.png$$,
   $$Het aminozuur DAP is niet in Binas opgenomen.$$, 'inline'),
  ('e77a1241-aadf-4137-adbe-d19058b7f522', '0f6ea0db-b8b6-49dd-9dfc-7edc8c28ccca', $$figuur 3 — crosslinks tussen parallelle mureïne-ketens$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-ii-celwand-context8.png$$,
   $$De verschillende sacharide-ketens van mureïne liggen parallel aan elkaar (herhalende eenheden ~NAM-NAG-NAM-NAG-NAM-NAG~). Tussen de peptideketens aan de NAM-eenheden worden peptidebindingen gevormd, waardoor crosslinks ontstaan, zoals schematisch weergegeven in figuur 3: drie parallelle sacharide-ketens met neerhangende peptideketens, waarbij sommige peptideketens onderling verbonden zijn via een crosslink (aangegeven met twee verbonden bolletjes).$$, 'inline'),
  ('4e28d288-81a0-4cd6-a16f-dca1b94098e8', '0f6ea0db-b8b6-49dd-9dfc-7edc8c28ccca', $$crosslinks tussen het derde en vierde aminozuur bij E. coli; uitwerkbijlage vraag 28$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-ii-celwand-context9.png$$,
   $$Bij E. coli komen crosslinks voor tussen het derde en het vierde aminozuur in de peptideketens. Op de uitwerkbijlage zijn de structuurformules van twee mureïne-ketens van E. coli tweemaal weergegeven: eenmaal vóór en eenmaal ná de vorming van de crosslink. In de weergave ‘na vorming crosslink’ zijn van sommige aminozuren enkele O- en H-atomen weggelaten.$$, 'inline'),
  ('ef6a2ae9-f7ee-436b-ba1f-19c7ef0be759', '0f6ea0db-b8b6-49dd-9dfc-7edc8c28ccca', $$uitwerkbijlage vraag 28 — twee mureïne-ketens vóór en ná crosslinkvorming$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-ii-celwand-context10.png$$,
   $$uitwerkbijlage bij vraag 28: de volledige structuurformules van twee parallelle mureïne-ketens (elk met de vier aminozuren van figuur 2, tussen ~NAG-NAM-NAG~-eenheden), tweemaal afgedrukt — links de situatie 'voor vorming crosslink' (aminozuur 3 en 4 van de linkerketen nog niet verbonden met de rechterketen) en rechts de situatie 'na vorming crosslink', waar bij aminozuur 3 en 4 een deel van de atomen is weggelaten zodat de leerling de ontbrekende peptidebinding met H- en O-atomen kan aanvullen.$$, 'uitwerkbijlage');
insert into practice_questions (id, exercise_id, question_number, topics, keywords, question_summary, question_image_url, question_text, context_block_ids) values
  ('0f18b96a-98b4-4e79-b1f9-f69ec52d0bdb', 'dc80d8ab-4c64-45f8-b0a1-840da565760c', 1,
   '[{"domain": "Reacties", "subdomain": "Energie"}]'::jsonb,
   '["reactiewarmte berekenen", "vormingswarmte", "waterstof", "koolstofdioxide", "Binas"]'::jsonb,
   $$Berekenen van de reactiewarmte van de vorming van CO en H₂ uit CO₂ en water$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-ii-kerosine-vraag1.png$$, $$Bereken de reactiewarmte voor reactie 1 per mol water. Neem aan dat onder deze omstandigheden de waardes van de vormingswarmten uit Binas mogen worden gebruikt.$$, array['32b7b5ec-7b39-4035-b065-1767623181f5']::uuid[]),
  ('a33c466b-38d8-4824-b7a8-9b50e78012dc', 'dc80d8ab-4c64-45f8-b0a1-840da565760c', 2,
   '[{"domain": "Reacties", "subdomain": "Chemische processen"}]'::jsonb,
   '["reactievergelijking opstellen", "cerium(III)oxide", "cerium(IV)oxide", "redoxreactie", "zuurstof"]'::jsonb,
   $$Opstellen van de reactievergelijking voor de omzetting van cerium(III)oxide door zuurstof$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-ii-kerosine-vraag2.png$$, $$Geef de vergelijking voor reactie 2.$$, array['113ee20d-bbc2-45d0-b2f5-aeac745eab89']::uuid[]),
  ('d640e31b-1264-43da-aa72-b37f33b06bd1', 'dc80d8ab-4c64-45f8-b0a1-840da565760c', 3,
   '[{"domain": "Rekenen en analyse", "subdomain": "Grootheden en relaties"}]'::jsonb,
   '["molverhouding berekenen", "cerium(III)oxide", "stoichiometrie", "zuurstof", "reactievergelijking"]'::jsonb,
   $$Berekenen van de benodigde hoeveelheid cerium(III)oxide om alle gevormde zuurstof weg te vangen$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-ii-kerosine-vraag3.png$$, $$Geef aan hoeveel mol cerium(III)oxide minimaal aanwezig moet zijn per mol CO₂ voor het wegvangen van alle zuurstof die ontstaat bij reactie 1. Licht je antwoord toe.$$, array['32b7b5ec-7b39-4035-b065-1767623181f5', '113ee20d-bbc2-45d0-b2f5-aeac745eab89']::uuid[]),
  ('ac813a41-5e81-49e8-997e-fa29248c10cb', 'dc80d8ab-4c64-45f8-b0a1-840da565760c', 4,
   '[{"domain": "Technologie en duurzaamheid", "subdomain": "Industriële processen"}]'::jsonb,
   '["blokschema", "continuproces", "reactor", "stofstroom", "batchproces"]'::jsonb,
   $$Ontwerpen van een blokschema voor een continuproces van CO- en H₂-productie$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-ii-kerosine-vraag4.png$$, $$Geef een mogelijk blokschema van deze productie van CO en H₂. Uit het antwoord moet blijken dat het proces als een continuproces verloopt. Geef reactoren en stofstromen weer. Zet bij alle stofstromen de namen en/of formules van de stoffen.$$, array['32b7b5ec-7b39-4035-b065-1767623181f5', '113ee20d-bbc2-45d0-b2f5-aeac745eab89', '7df4e1b7-2f17-4bdf-85ad-c591edeea6a2']::uuid[]),
  ('6a39217f-d1d8-4fcf-ac4f-a07260ff73bb', 'dc80d8ab-4c64-45f8-b0a1-840da565760c', 5,
   '[{"domain": "Reacties", "subdomain": "Chemische processen"}]'::jsonb,
   '["Fischer-Tropsch-proces", "reactievergelijking opstellen", "syngas", "kerosine", "koolwaterstof"]'::jsonb,
   $$Opstellen van de reactievergelijking voor de vorming van kerosine met het Fischer-Tropsch-proces$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-ii-kerosine-vraag5.png$$, $$Geef de vergelijking voor de vorming van deze kerosine met het Fischer-Tropsch-proces.$$, array['8a6a3069-2f6e-4c8b-aa4c-b421b158aba7']::uuid[]),
  ('14057294-9955-4659-ab4c-3e0831d1a7b7', 'dc80d8ab-4c64-45f8-b0a1-840da565760c', 6,
   '[{"domain": "Rekenen en analyse", "subdomain": "Grootheden en relaties"}]'::jsonb,
   '["gaswet berekenen", "dichtheid", "molaire massa", "koolstofdioxide", "kerosine"]'::jsonb,
   $$Berekenen van de hoeveelheid afgevangen CO₂ bij de productie van een bepaald volume kerosine$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-ii-kerosine-vraag6.png$$, $$Bereken hoeveel ton CO₂ wordt afgevangen voor het produceren van 20 m³ van deze kerosine (T = 298 K, p = p₀). Ga er bij de berekening van uit dat geen andere koolwaterstoffen dan kerosine ontstaan. Maak gebruik van de volgende gegevens:
− neem aan dat H₂ in overmaat beschikbaar is;
− de dichtheid van de kerosine bedraagt 7,9·10⁻¹ g mL⁻¹.$$, array['32b7b5ec-7b39-4035-b065-1767623181f5', '8a6a3069-2f6e-4c8b-aa4c-b421b158aba7']::uuid[]),
  ('fd73728a-abce-40c5-ab04-b3256f473a2e', '65bad1bb-d26a-4901-a503-e24bb8e089d6', 7,
   '[{"domain": "Rekenen en analyse", "subdomain": "Grootheden en relaties"}]'::jsonb,
   '["volumepercentage berekenen", "gaswet", "grenswaarde", "stikstofoxiden", "concentratie"]'::jsonb,
   $$Vergelijken van het gemeten volumepercentage NO₂ met de grenswaarde met een berekening$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-ii-knoxout-vraag7.png$$, $$Laat met een berekening zien of het gemeten gemiddelde volumepercentage NO₂ hoger of lager was dan de grenswaarde van NO₂ (TGG 8 uur). (T = 298 K, p = p₀)$$, array['ac8885c5-802a-4254-be1a-8a20fa5c0336']::uuid[]),
  ('0849d46b-b5d9-45c9-a473-fee230aef4fe', '65bad1bb-d26a-4901-a503-e24bb8e089d6', 8,
   '[{"domain": "Reacties", "subdomain": "Chemische processen"}]'::jsonb,
   '["redoxreactie", "zuur-basereactie", "reactiesoort herkennen", "katalysator", "TiO2"]'::jsonb,
   $$Bepalen of de omzetting van water en zuurstof door TiO₂ een redoxreactie of een zuur-basereactie is$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-ii-knoxout-vraag8.png$$, $$Leg mede aan de hand van de formules van de betrokken deeltjes uit of deze omzetting van water en zuurstof kan worden opgevat als een redoxreactie of als een zuur-basereactie.$$, array['f32226aa-4f02-45ba-ae1b-c041f828414d']::uuid[]),
  ('d5744afe-e1bb-419b-a299-ab3ebafc156b', '65bad1bb-d26a-4901-a503-e24bb8e089d6', 9,
   '[{"domain": "Reacties", "subdomain": "Chemische processen"}]'::jsonb,
   '["reactievergelijking opstellen", "zuur-basereactie", "calciumcarbonaat", "salpeterzuur", "neutralisatie"]'::jsonb,
   $$Opstellen van de reactievergelijking van de neutralisatie van salpeterzuur door calciumcarbonaat$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-ii-knoxout-vraag9.png$$, $$Geef de vergelijking van de reactie van calciumcarbonaat met opgelost salpeterzuur waarbij onder andere CO₂ en opgelost calciumnitraat ontstaan.$$, array['4e7cca14-c08b-43f2-8b3b-c09ac32a901f']::uuid[]),
  ('1bddbb62-cdf9-490a-a125-2dfc5d078038', '65bad1bb-d26a-4901-a503-e24bb8e089d6', 10,
   '[{"domain": "Rekenen en analyse", "subdomain": "Grootheden en relaties"}]'::jsonb,
   '["massaberekening", "dichtheid", "molverhouding berekenen", "calciumcarbonaat", "neutralisatie"]'::jsonb,
   $$Berekenen of de hoeveelheid calciumcarbonaat in de verf voldoende is om vijf jaar salpeterzuur te neutraliseren$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-ii-knoxout-vraag10.png$$, $$Leg uit, met behulp van een berekening van de benodigde massa aan calciumcarbonaat per m² muur, of de verf gedurende vijf jaar het ontstane salpeterzuur kan neutraliseren. Maak onder andere gebruik van de volgende gegevens:
− per m² muur is 0,40 L verf nodig;
− de dichtheid van de verf bedraagt 1,52 kg L⁻¹;
− de gemiddelde molaire massa van NOₓ is 30,8 g mol⁻¹.$$, array['4e7cca14-c08b-43f2-8b3b-c09ac32a901f', 'e785b5e4-faff-42d7-9f27-12369ec91312']::uuid[]),
  ('8072ba33-6a55-4148-abfd-b0845feb37eb', '4224a8a5-4ba9-4803-96ff-45e5770c3517', 11,
   '[{"domain": "Materie", "subdomain": "Deeltjesmodellen"}]'::jsonb,
   '["Lewisstructuur", "formele lading", "ion", "siliciumcluster", "VSEPR"]'::jsonb,
   $$Tekenen van de Lewisstructuur van het ion Si₄⁴⁻ met formele ladingen$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-ii-batterijen-vraag11.png$$, $$Geef de Lewisstructuur van een ion Si₄⁴⁻. Geef formele ladingen aan.$$, array['82619aac-c48e-4b98-ae1b-e6c9530cce09']::uuid[]),
  ('ff9e7575-726b-4329-9b40-12966a623b36', '4224a8a5-4ba9-4803-96ff-45e5770c3517', 12,
   '[{"domain": "Rekenen en analyse", "subdomain": "Grootheden en relaties"}]'::jsonb,
   '["rendement berekenen", "waterstofgas", "gaswet", "molaire massa", "natriumsilicide"]'::jsonb,
   $$Berekenen van het rendement van de waterstofproductie uit natriumsilicide en water$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-ii-batterijen-vraag12.png$$, $$Bereken het rendement van de waterstofproductie in de oplader (T = 298 K, p = p₀).$$, array['630ebc2b-b199-4f2f-9c83-eccd9e568d01']::uuid[]),
  ('3d36286d-d3a6-4710-98b1-961cb1dad1f6', '4224a8a5-4ba9-4803-96ff-45e5770c3517', 13,
   '[{"domain": "Reacties", "subdomain": "Chemische processen"}, {"domain": "Reacties", "subdomain": "Energie"}]'::jsonb,
   '["waterstofbrandstofcel", "reactievergelijking opstellen", "energieomzetting", "energiebehoud", "verbranding van waterstof"]'::jsonb,
   $$Opstellen van de reactievergelijking in de brandstofcel en uitleggen dat het toegevoegde water niet de energiebron is$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-ii-batterijen-vraag13.png$$, $$Geef de vergelijking van de reactie die verloopt in de waterstofbrandstofcel en leg uit dat de energie die de oplader levert niet wordt geleverd door het toegevoegde water.$$, array['630ebc2b-b199-4f2f-9c83-eccd9e568d01', 'f416852a-1986-4429-8230-33ed6de897a5']::uuid[]),
  ('d055e2ec-9f75-4582-a69a-066682129ac5', '4224a8a5-4ba9-4803-96ff-45e5770c3517', 14,
   '[{"domain": "Technologie en duurzaamheid", "subdomain": "Groene chemie"}]'::jsonb,
   '["groene chemie", "duurzaamheid", "grondstofgebruik", "energiegebruik", "afvalverwerking"]'::jsonb,
   $$Beoordelen welke uitgangspunten van groene chemie niet worden nageleefd bij de productie en het gebruik van de oplader$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-ii-batterijen-vraag14.png$$, $$Noteer bij elk van de volgende uitgangspunten in de groene chemie een gegeven waaruit blijkt dat niet wordt voldaan aan deze uitgangspunten. Gebruik gegevens uit de voorgaande teksten over de productie en het gebruik van de oplader. Gebruik onder andere Binas-tabel 97F. Noteer je antwoord als volgt:
− Uitgangspunt 2: …
− Uitgangspunt 6: …
− Uitgangspunt 12: …$$, array['82619aac-c48e-4b98-ae1b-e6c9530cce09', '630ebc2b-b199-4f2f-9c83-eccd9e568d01', 'd580e96c-76f1-4564-aa21-a87edcb9e310']::uuid[]),
  ('f99667b5-abec-44e9-8236-d8af3cf48293', '4224a8a5-4ba9-4803-96ff-45e5770c3517', 15,
   '[{"domain": "Reacties", "subdomain": "Reactiesnelheid en katalyse"}]'::jsonb,
   '["reactiesnelheid", "botsende-deeltjesmodel", "natriumsilicide", "natriumboorhydride", "exotherme reactie"]'::jsonb,
   $$Verklaren waarom natriumboorhydride sneller reageert met water wanneer het gemengd is met natriumsilicide$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-ii-batterijen-vraag15.png$$, $$Geef een verklaring voor het gegeven dat zuiver natriumboorhydride slechts moeizaam met water reageert, maar wel snel reageert als het is gemengd met natriumsilicide.$$, array['dec1d19d-dd79-4110-9895-98ed33f43853']::uuid[]),
  ('9de0df1e-4fc1-47fd-8132-e006c9835d2f', '4224a8a5-4ba9-4803-96ff-45e5770c3517', 16,
   '[{"domain": "Reacties", "subdomain": "Chemische processen"}]'::jsonb,
   '["reactievergelijking opstellen", "natriumboorhydride", "waterstofgas", "natriumhydroxide", "hydrolyse"]'::jsonb,
   $$Opstellen van de reactievergelijking van natriumboorhydride met water$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-ii-batterijen-vraag16.png$$, $$Geef de vergelijking van reactie 2.$$, array['61718862-4dfd-4bf8-9d19-2bd864350bb8']::uuid[]),
  ('3214e1f1-071b-4fde-a3d1-8aac2352b1e2', '4224a8a5-4ba9-4803-96ff-45e5770c3517', 17,
   '[{"domain": "Rekenen en analyse", "subdomain": "Grootheden en relaties"}]'::jsonb,
   '["massaverhouding berekenen", "stoichiometrie", "natriumsilicide", "natriumboorhydride", "rendement"]'::jsonb,
   $$Berekenen van de massa natriumsilicide in het mengsel met natriumboorhydride met behulp van beide reactievergelijkingen$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-ii-batterijen-vraag17.png$$, $$Bereken met behulp van reacties 1 en 2 hoeveel gram natriumsilicide aanwezig is in 100 g van dit mengsel. Neem aan dat het rendement van beide reacties 100% bedraagt.$$, array['630ebc2b-b199-4f2f-9c83-eccd9e568d01', '61718862-4dfd-4bf8-9d19-2bd864350bb8']::uuid[]),
  ('f7fc44d9-d35e-45ed-8ebd-5e15fda24956', 'f2c4ed1f-d0ce-4ce0-893a-f4d6e87ba169', 18,
   '[{"domain": "Materie", "subdomain": "Deeltjesmodellen"}]'::jsonb,
   '["Lewisstructuur", "radicaal", "formele lading", "sulfaation", "covalentie"]'::jsonb,
   $$Tekenen van de Lewisstructuur van het radicaal SO₄•⁻$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-ii-zwetend-vraag18.png$$, $$Geef een mogelijke Lewisstructuur van het deeltje SO₄•⁻, waaruit blijkt dat het deeltje een radicaal is. Geef formele ladingen aan. Neem aan dat de covalentie van zwavel zes is.$$, array['006b2179-e9ff-4c71-af0a-b941d2e8363d']::uuid[]),
  ('ebd6a9a4-bf72-4213-bbfe-64941f60f0cf', 'f2c4ed1f-d0ce-4ce0-893a-f4d6e87ba169', 19,
   '[{"domain": "Reacties", "subdomain": "Reactiekinetiek"}]'::jsonb,
   '["propagatiereactie", "additiepolymerisatie", "radicaal", "elektronenverplaatsing", "HEMA"]'::jsonb,
   $$Opstellen van de propagatiereactie tussen het radicaal SO₄•⁻ en HEMA met elektronenverplaatsing$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2017-ii-zwetend-vraag19.png$$, $$Geef de vergelijking van de propagatiereactie van een deeltje SO₄•⁻ met een molecuul HEMA. Geef het deeltje SO₄•⁻ aan met R•. Geef met pijlen aan hoe elektronen zich verplaatsen tijdens de reactie.$$, array['f83adb88-8bef-4c33-a1b0-9a12ee1398b8', '9f11c75d-412e-4d43-8545-c8e333baf0ef']::uuid[]),
  ('6d0cb89a-4435-4b83-a067-47927cf77e57', 'f2c4ed1f-d0ce-4ce0-893a-f4d6e87ba169', 20,
